il.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                AS \"Stock Category DESC\",     ril.REPL_ORDER_CTRL                                AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'         ELSE ril.REPL_ORDER_CTRL     END                                                 AS \"Order Control DESC\",      ril.SOURCE_WH                                   AS \"Source Warehouse\",     ril.PRIMARY_REPL_SUPPLIER                       AS \"Repl Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     isc.ORIGIN_COUNTRY_ID                           AS \"Origin Country\",     isc.PRIMARY_SUPP_IND                            AS \"Primary Supp IND\",     isc.LEAD_TIME                                   AS \"Supp Lead Time Days\",     isc.PICKUP_LEAD_TIME                            AS \"Supp Pickup Lead Time Days\",     iscl.PICKUP_LEAD_TIME                           AS \"LOC Pickup Lead Time Days\",     NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)AS \"Effective Pickup Lead Time\",     ril.SUPP_LEAD_TIME                              AS \"Repl Supp Lead Time Days\",     ril.WH_LEAD_TIME                                AS \"WH Lead Time Days\",     ril.PICKUP_LEAD_TIME                            AS \"Repl Pickup Lead Time Days\",     ril.ADJ_SUPP_LEAD_TIME                          AS \"Adj Supp Lead Time\",     ril.ADJ_PICKUP_LEAD_TIME                        AS \"Adj Pickup Lead Time\",      CASE         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) IS NULL         THEN 'MISSING'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) = 0         THEN 'ZERO - REVIEW'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) &gt; 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                 AS \"Pickup Lead Time Status\",      CASE         WHEN isc.LEAD_TIME IS NULL  THEN 'MISSING'         WHEN isc.LEAD_TIME = 0      THEN 'ZERO - REVIEW'         WHEN isc.LEAD_TIME &gt; 0      THEN 'OK'     END                                                 AS \"Supp Lead Time Status\",      CASE         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME IS NULL         THEN 'MISSING'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME = 0         THEN 'ZERO - REVIEW'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME &gt; 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                 AS \"WH Lead Time Status\",      CASE         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME &lt;&gt; isc.PICKUP_LEAD_TIME         THEN 'LOC OVERRIDE ACTIVE'         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME = isc.PICKUP_LEAD_TIME         THEN 'LOC MATCHES GLOBAL'         ELSE 'USING GLOBAL DEFAULT'     END                                               AS \"Lead Time Override Status\",      CASE         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'SUPPLIER MISSING ON REPL'         ELSE 'OK'     END                                                 AS \"Supplier Setup Status\",      CASE         WHEN (ril.STOCK_CAT IN ('C','D','L','W')               AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) IS NULL)           OR  isc.LEAD_TIME IS NULL           OR (il.LOC_TYPE = 'S'               AND ril.STOCK_CAT IN ('C','L','W')               AND ril.WH_LEAD_TIME IS NULL)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'FAIL - ACTION REQUIRED'         WHEN (ril.STOCK_CAT IN ('C','D','L','W')               AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) = 0)           OR  isc.LEAD_TIME = 0           OR (il.LOC_TYPE = 'S'               AND ril.STOCK_CAT IN ('C','L','W')               AND ril.WH_LEAD_TIME = 0)         THEN 'WARNING - ZERO VALUE'         ELSE 'PASS'     END                                                 AS overall_validation_result,      TRUNC(SYSDATE)                                     AS \"Report Date\"  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                  = il.ITEM                                                      AND  ril.LOCATION              = il.LOC      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                  = im.ITEM                                                      AND  im.TRAN_LEVEL             = im.ITEM_LEVEL      JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                   = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                   = c.DEPT                                                      AND  im.CLASS                  = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                   = sc.DEPT                                                      AND  im.CLASS                  = sc.CLASS                                                      AND  im.SUBCLASS               = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                  = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM                  = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = iscl.SUPPLIER                                                      AND  iscl.LOC                  = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION              = st.STORE                                                      AND  il.LOC_TYPE               = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION              = wh.WH                                                      AND  il.LOC_TYPE               = 'W'  WHERE     ril.REPL_METHOD IS NOT NULL     AND il.STATUS   IN ('A', 'C')     AND im.STATUS    = 'A'  ORDER BY     overall_validation_result DESC,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     il.LOC_TYPE,     location_name</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Dept No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Dept Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass Name</ds:name><ds:datatype>varchar(120)</ds:datatype>